v8OpenTrade=async function(){if(!currentSession){showSessionHub();return;}const request=++V8E.tradeRequest,epoch=V8E.epoch,owner=currentUser?.id,session=currentSession.id,button=nav.querySelector('[data-v8-nav=trade]');button.setAttribute('aria-busy','true');try{await loadSessionTrades();if(request!==V8E.tradeRequest||epoch!==V8E.epoch||owner!==currentUser?.id||session!==currentSession?.id)return;const open=sessionTrades.filter(t=>!t.exit_at);if(open.length===1){journalScope='current';await openJournalTradeById(open[0].id);}else if(open.length){await v8OpenSessionTrades();}else v810OpenEntry(false);}catch(e){if(owner===currentUser?.id)message('Trades nicht geladen: '+e.message,true);}finally{if(request===V8E.tradeRequest)button.removeAttribute('aria-busy');}};
