async function v810Action(action,payload={},session=currentSession?.id,request=crypto.randomUUID(),expected=null){const {data,error}=await client.rpc('session_action_v810',{p_session_id:session,p_request_id:request,p_action:action,p_payload:payload,p_expected_context:expected});if(error)throw error;if(!data?.session?.id)throw Error('Keine Speicherbestätigung erhalten.');return data;}
function v810DrawClose(data){const host=$('v810ClosePreview');host.replaceChildren();const p=document.createElement('p');p.textContent=data.open_trades+' offene Trades · können nach Session-Ende weiter dokumentiert werden';host.append(p);if(data.rule_breaches){const warning=document.createElement('p');warning.textContent=data.rule_breaches+' Trades mit dokumentierten Regelabweichungen · Details bleiben im Review.';host.append(warning);}const list=document.createElement('ul');for(const point of data.missing||[]){const li=document.createElement('li');li.textContent=point;list.append(li);}if(list.children.length)host.append(list);else{const p=document.createElement('p');p.textContent='Vorbereitung bestätigt · keine Pflichtlücken.';host.append(p);}}
async function v810OpenClose(){if(!currentSession||V810.closing)return;v8SetLimitOpen(false);const owner=currentUser?.id,id=currentSession.id;closure.dataset.session=id;closure.dataset.request=crypto.randomUUID();$('v810CloseAck').checked=false;$('v810CloseSave').disabled=true;$('v810CloseStatus').textContent='Abschluss wird geprüft …';if(!closure.open)closure.showModal();try{const data=await v810Action('preview',{},id);if(owner!==currentUser?.id||closure.dataset.session!==id)return;v810DrawClose(data);$('v810CloseStatus').textContent='';$('v810CloseSave').disabled=false;}catch(e){$('v810CloseStatus').textContent='Prüfung nicht bestätigt: '+e.message;}}
$('v810CloseSave').onclick=async(event)=>{if(V810.closing||!$('v810CloseAck').checked){$('v810CloseStatus').textContent='Abschluss zuerst bewusst bestätigen.';return;}const id=closure.dataset.session,owner=currentUser?.id;V810.closing=true;$('v810CloseSave').disabled=true;try{const data=await v810Action('close',{},id,closure.dataset.request);if(data.session.status!=='closed'||!data.session.closed_at)throw Error('Abschluss nicht bestätigt.');if(owner!==currentUser?.id)return;if(event?.isTrusted)V810.closeTap={x:event.clientX,y:event.clientY,until:Date.now()+600};$('v810CloseStatus').textContent='';closure.close();if(currentSession?.id===id)currentSession=null;V810.documenting=false;V810.startId=null;V810.confirmRequest=null;V8Prep.pollSeq++;V8Prep.polling=false;V8Prep.totals=null;sessionTrades=[];V8Prep.anchor=null;v8SetLimitOpen(false);renderSession();showView('live');saveWorkspace();message('Handelssession beendet. Offene Trades bleiben offen.');await Promise.allSettled([loadCount(),loadSessionTrades(),v810LoadAftercare(),v810LoadOtherOpen(true)]);}catch(e){$('v810CloseStatus').textContent='Abschluss nicht bestätigt: '+e.message+' · Erneut versuchen; es entsteht kein doppelter Abschluss.';}finally{V810.closing=false;$('v810CloseSave').disabled=false;}};
