$('confirmSession').onclick=async()=>{if(busy)return;const selection=getSessionSelection().map(row=>({...row,copy_mode:$('v813SessionCopy').checked,copy_leader:$('v813SessionCopy').checked&&row.account_id===$('sessionLeader814').value}));if(!selection.length||selection.some(a=>!Number.isSafeInteger(a.planned_quantity)||a.planned_quantity<1||!Number.isSafeInteger(a.initial_sl_ticks)||a.initial_sl_ticks<1||a.initial_sl_ticks>100000)){sessionFeedback('Mindestens ein Konto mit ganzen Kontrakten und gültigem SL wählen.');return;}const owner=currentUser?.id,fields=captureFields(personal),acks={...V8Prep.acks},ack=V8H.ack,retrospective=v810Retrospective(),mode=sessionDraftMode;busy=true;$('confirmSession').disabled=true;try{V810.startId=V810.startId||crypto.randomUUID();saveWorkspace();const id=currentSession?.id||V810.startId;const result=await v810Action(mode==='start'?'start':'accounts',{selected_accounts:selection},id,V810.startId,currentSession?.htf_context||{});if(owner!==currentUser?.id)return;currentSession=result.session;renderSession();applyFields(personal,fields);V811.limitsEnabled=$('v811LimitsEnabled').checked;$('v811MoneyLimits').hidden=!V811.limitsEnabled;V8Prep.acks=acks;V8H.ack=ack;V8Prep.owner=owner;V8Prep.session=currentSession.id;renderDecision();v8UpdateMental();if($('v8RememberStandards').checked){const defaults=v8AccountDefaults();for(const row of selection)defaults[row.account_id]=row;try{ttLocalStore.setItem('tt8_account_standards_'+owner,JSON.stringify(defaults));}catch(_){}}if(retrospective){v810OpenEntry(true);}else if(result.reused&&sessionReady()){v810OpenEntry(false);}else{showView('session');v8ShowPrepStep(3);}await Promise.allSettled([loadSessionTrades(),renderHtfImage()]);saveWorkspace();}catch(e){sessionFeedback('Konten nicht bestätigt: '+e.message);}finally{busy=false;$('confirmSession').disabled=false;}};
