const preparationDisplay810=v8UpdatePreparation;
v8UpdatePreparation=function(){preparationDisplay810();const missing=v8PreparationMissing();$('sessionCheckStatus').textContent=missing.length?missing.length+' Pflichtpunkte offen':sessionReady()?'Vorbereitung bestätigt · Änderungen erst mit erneuter Bestätigung gespeichert':'Alle Pflichtpunkte ausgefüllt · Bestätigung noch erforderlich';};
$('saveHtf').onclick=async()=>{if(busy||!currentSession)return;const missing=v8PreparationMissing();if(missing.length){v8FocusPreparation(missing[0][1]);return;}const id=currentSession.id,owner=currentUser?.id,plan=v8HtfPlan(),risks=v8MentalRisks(readScales($('sessionMoodOptions')));const context={notes:[plan.news,plan.sentiment,plan.direction].join('\n'),free_notes:plan.notes,mental_check:{scales:readScales($('sessionMoodOptions')),critical_factors:risks,conscious_continue:risks.length?V8H.ack===v8MentalSignature():false},preflight_checks:{structure:true,levels:true,events:true,risk:true}};const signature=JSON.stringify({plan:{...plan,personal_plan:{...plan.personal_plan,started_at:null,end_at:null}},context});if(V810.confirmRequest?.signature!==signature)V810.confirmRequest={id:crypto.randomUUID(),signature,payload:{plan,context},expected:currentSession.htf_context||{}};saveWorkspace();busy=true;$('saveHtf').disabled=true;try{const data=await v810Action('confirm',V810.confirmRequest.payload,id,V810.confirmRequest.id,V810.confirmRequest.expected);if(owner!==currentUser?.id||currentSession?.id!==id)return;currentSession=data.session;V8Prep.anchor=currentSession.htf_context.htf_v8.plan.personal_plan.started_at;V810.confirmRequest=null;V810.documenting=false;V8H.request=null;v8RefreshHome();v8UpdateHtfBadge();syncEntrySession();v810OpenEntry(false);saveWorkspace();void v8PollSessionLimits();message('Vorbereitung bestätigt · Trade vorbereiten.');}catch(e){$('v8HtfFeedback').textContent='Vorbereitung nicht bestätigt: '+e.message+' · Entwurf bleibt erhalten.';}finally{busy=false;$('saveHtf').disabled=false;v8UpdatePreparation();}};
