// Read-only synchronization never reapplies local stale form data over server confirmation.
async function v810Sync(){if(!currentUser||V810.syncing||busy||V810.closing||closure.open)return;const owner=currentUser.id,id=currentSession?.id;V810.syncing=true;try{const {data,error}=await client.from('trading_sessions').select('id,session_date,status,htf_context,created_at,closed_at').eq('status','open').order('created_at',{ascending:false}).limit(1);if(error)throw error;if(owner!==currentUser?.id)return;const next=data?.[0]||null;if(next?.id!==id){if(v8PauseVisible()){const key=v8PauseKey();if(key){try{ttLocalStore.removeItem(key);ttSessionStore.removeItem(key);}catch(_){}}V8P.until=null;V8P.origin=null;v8SetPauseOpen(false);}currentSession=next;V810.documenting=false;V8Prep.anchor=next?.htf_context?.htf_v8?.plan?.personal_plan?.started_at||null;sessionTrades=[];v8SetLimitOpen(false);renderSession();showView('live');}else if(next&&JSON.stringify(next.htf_context)!==JSON.stringify(currentSession.htf_context)){currentSession=next;V8Prep.anchor=next.htf_context?.htf_v8?.plan?.personal_plan?.started_at||null;v8RefreshHome();syncEntrySession();}if(next){const result=await client.from('session_events_v810').select('event_key').eq('session_id',next.id).eq('kind','warning_ack');if(!result.error&&owner===currentUser?.id&&currentSession?.id===next.id){const seen=v8SeenLimits();for(const e of result.data||[])seen.add(e.event_key);try{ttLocalStore.setItem(v8LimitSeenKey(),JSON.stringify([...seen]));}catch(_){}}}}catch(_){/* Keep local draft; all writes still use authoritative CAS. */}finally{V810.syncing=false;}}
