async function v810LoadAftercare(){const owner=currentUser?.id;if(!owner)return;const host=$('v810SessionHistory');host.textContent='Wird geladen …';try{const sessions=await readAllRows('trading_sessions','id,session_date,status,closed_at,htf_context',q=>q.eq('status','closed').order('closed_at',{ascending:false}).order('id'));const events=await readAllRows('session_events_v810','id,session_id,kind,payload,created_at',q=>q.order('created_at').order('id'));if(owner!==currentUser?.id)return;host.replaceChildren();for(const s of sessions){const box=document.createElement('details'),title=document.createElement('summary');title.textContent=s.session_date+' · beendet '+v8DateTime(s.closed_at);box.append(title);for(const e of events.filter(e=>e.session_id===s.id)){const p=document.createElement('p');p.textContent=v8DateTime(e.created_at)+' · '+(e.kind==='closed'?(e.payload.missing?.length?'Regelverletzung: '+e.payload.missing.join(', '):'Ohne Pflichtlücken beendet'):e.kind==='supplement'?'Nachträglich ergänzt: '+JSON.stringify(e.payload):e.kind);box.append(p);}const note=document.createElement('textarea');note.rows=2;note.maxLength=3000;note.setAttribute('aria-label','Tatsächliche Ergänzung zur Session '+s.session_date);note.placeholder='Fehlende Punkte mit tatsächlichen Angaben ergänzen; unbekannt bleibt unbekannt.';const status=document.createElement('p');status.setAttribute('role','status');let request=null;const save=v8Button('Nachträgliche Angaben speichern',async()=>{const text=note.value.trim();if(!text){status.textContent='Tatsächliche Ergänzung eingeben.';return;}save.disabled=true;request=request||crypto.randomUUID();try{await v810Action('supplement',{note:text},s.id,request);note.value='';request=null;await v810LoadAftercare();}catch(e){status.textContent='Ergänzung nicht bestätigt: '+e.message;}finally{save.disabled=false;}},'secondary');const trades=v8Button('Zugehörige Trades dokumentieren',async()=>{const rows=await readAllRows('trades','*',q=>q.eq('session_id',s.id).order('entry_at').order('id'));if(owner!==currentUser?.id)return;journalScope='history';showView('journal');$('sessionTrades').classList.remove('hidden');$('sessionTradeList').classList.remove('hidden');$('tradeDetails').classList.add('hidden');$('sessionTradeList').replaceChildren();for(const t of rows){const b=v8Button(tradeLabel(t)+' · '+(t.exit_at?'Exit dokumentiert':'Trade noch offen'),()=>openJournalTradeById(t.id),'secondary');$('sessionTradeList').append(b);}},'ghost');box.append(note,save,status,trades);host.append(box);}if(!sessions.length)host.textContent='Noch keine abgeschlossenen Sessions.';}catch(e){host.textContent='Historie nicht geladen: '+e.message;}}
