async function v810LoadOtherOpen(force=false){if(!currentUser||otherOpenBusy810||!force&&Date.now()-otherOpenAt810<20000)return;const owner=currentUser.id,seq=++otherOpenRequest810;otherOpenBusy810=true;try{const rows=await readAllRows('trades','id,session_id,setup_type,instrument,direction,entry_at,exit_at',q=>q.is('exit_at',null).order('entry_at').order('id'));if(owner!==currentUser?.id||seq!==otherOpenRequest810)return;const others=rows.filter(t=>!t.exit_at&&t.session_id!==currentSession?.id);otherOpen810.replaceChildren();otherOpen810.hidden=!others.length;if(others.length){const title=document.createElement('h3');title.textContent=others.length+' weitere offene Trades';otherOpen810.append(title);const p=document.createElement('p');p.textContent='Diese Trades bleiben unabhängig vom Session-Ende offen.';otherOpen810.append(p);for(const t of others)otherOpen810.append(v8Button(t.instrument+' · '+t.setup_type+' · '+v8DateTime(t.entry_at)+' · dokumentieren',()=>openJournalTradeById(t.id),'secondary'));}otherOpenAt810=Date.now();}catch(_){if(owner===currentUser?.id){otherOpen810.hidden=false;otherOpen810.textContent='Weitere offene Trades konnten nicht geprüft werden.';}}finally{if(seq===otherOpenRequest810)otherOpenBusy810=false;}}
